class FeedState {
  const FeedState({this.items = const [], this.loading = false});
  final List<Item> items;
  final bool loading;

  // ❌ what this class had: List.== is identity, so a freshly built list
  //    is never equal to the old one, and Object.hash(items, ...) hashes
  //    the list's identity rather than its contents.
  // bool operator ==(Object o) => o is FeedState && o.items == items;
  // int get hashCode => Object.hash(items, loading);

  @override
  bool operator ==(Object other) =>
      other is FeedState &&
      listEquals(other.items, items) &&
      other.loading == loading;

  @override
  int get hashCode => Object.hash(Object.hashAll(items), loading);
}

