// ❌ total stored as a field: a second source of truth for one fact
class CartState {
  const CartState({required this.lines, this.promo, required this.total});
  final List<Line> lines;
  final Promo? promo;
  final double total;

  // every writer has to remember to recompute it. This one didn't.
  CartState applyPromo(Promo p) =>
      CartState(lines: lines, promo: p, total: total);
}

// ✅ derived in getters: the object cannot disagree with its own inputs
class Cart {
  const Cart({this.lines = const [], this.promo});
  final List<Line> lines;
  final Promo? promo;

  double get subtotal => lines.fold(0, (sum, l) => sum + l.price * l.qty);
  double get total => promo == null ? subtotal : subtotal * (1 - promo!.rate);
  bool get isEmpty => lines.isEmpty;

  Cart applyPromo(Promo p) => Cart(lines: lines, promo: p);
}

// ✅ expensive enough to cache: cache in the HOLDER, keyed by its input
class CartCubit extends Cubit<Cart> {
  CartCubit() : super(const Cart());

  List<Line>? _cachedFor;
  List<Line>? _cache;

  List<Line> get sortedLines {
    if (identical(_cachedFor, state.lines)) return _cache!;
    _cachedFor = state.lines;                 // the key IS the input
    return _cache = [...state.lines]..sort((a, b) => a.name.compareTo(b.name));
  }
}
