class FavoriteCubit extends Cubit<bool> {
  FavoriteCubit(this._api, {required bool initial}) : super(initial);

  final Api _api;
  int _requestId = 0;

  // ❌ two fast taps: whichever response is slower wins the argument
  Future<void> toggleBroken() async {
    final next = !state;
    await _api.setFavorite(next);
    emit(next);
  }

  // ✅ each intent carries an id; replies for superseded intents are dropped
  Future<void> toggle() async {
    final id = ++_requestId;
    final next = !state;
    try {
      await _api.setFavorite(next);
    } on ApiException catch (e) {
      // nothing was emitted yet, so there is nothing to roll back — but only
      // the newest intent is allowed to report the failure
      if (id == _requestId && !isClosed) addError(e);
      return;
    }
    if (id != _requestId || isClosed) return;     // stale success: ignore it
    emit(next);
  }
}

// ✅ or let one queue own the ordering: only one write is ever in flight
class FavoriteBloc extends Bloc<FavoriteEvent, bool> {
  FavoriteBloc(this._api) : super(false) {
    // droppable() would ignore taps mid-save; sequential() runs them in order
    on<FavoriteToggled>(_onToggled, transformer: sequential());
  }

  final Api _api;

  Future<void> _onToggled(FavoriteToggled e, Emitter<bool> emit) async {
    await _api.setFavorite(e.value);
    emit(e.value);
  }
}

enum Sync { synced, pending, failed }

class Post {
  const Post({required this.id, required this.liked, this.sync = Sync.synced});
  final String id;
  final bool liked;
  final Sync sync;

  Post copyWith({bool? liked, Sync? sync}) =>
      Post(id: id, liked: liked ?? this.liked, sync: sync ?? this.sync);
}

class FeedCubit extends Cubit<List<Post>> {
  FeedCubit(this._api) : super(const []);

  final Api _api;
  final _errors = StreamController<String>.broadcast();
  Stream<String> get errors => _errors.stream;   // one-shot, not a state field

  Future<void> toggleLike(String id) async {
    final before = state.firstWhere((p) => p.id == id);   // the rollback value
    _put(before.copyWith(liked: !before.liked, sync: Sync.pending));

    try {
      await _api.setLiked(id, !before.liked);
      if (isClosed) return;
      _put(_row(id).copyWith(sync: Sync.synced));   // keep the optimistic value
    } catch (_) {
      if (isClosed) return;
      _put(before.copyWith(sync: Sync.failed));     // exactly what we replaced
      _errors.add('Could not save your like');
    }
  }

  Post _row(String id) => state.firstWhere((p) => p.id == id);
  void _put(Post p) => emit([for (final x in state) if (x.id == p.id) p else x]);

  @override
  Future<void> close() {
    _errors.close();
    return super.close();
  }
}

class PagedState<T> {
  const PagedState({
    this.items = const [],
    this.nextCursor,
    this.isLoadingMore = false,
    this.isRefreshing = false,
  });

  final List<T> items;
  final String? nextCursor;   // null = no further pages
  final bool isLoadingMore;
  final bool isRefreshing;

  bool get hasMore => nextCursor != null;          // derived, cannot drift
  bool get isEmpty => items.isEmpty && !hasMore && !isRefreshing;

  PagedState<T> busy({bool? more, bool? refreshing}) => PagedState(
        items: items,
        nextCursor: nextCursor,
        isLoadingMore: more ?? isLoadingMore,
        isRefreshing: refreshing ?? isRefreshing,
      );
}

class FeedStore extends ValueNotifier<PagedState<Post>> {
  FeedStore(this._repo) : super(const PagedState());
  final FeedRepository _repo;

  Future<void> loadMore() async {
    final from = value.nextCursor;
    if (from == null || value.isLoadingMore) return;   // re-entrancy guard
    value = value.busy(more: true);

    final page = await _repo.fetch(after: from);

    // the response is only valid for the state it was requested from
    if (value.nextCursor != from) return;              // a refresh landed first
    final seen = {for (final p in value.items) p.id};
    value = PagedState(
      items: [...value.items, ...page.items.where((p) => !seen.contains(p.id))],
      nextCursor: page.nextCursor,
    );
  }

  Future<void> refresh() async {
    value = value.busy(refreshing: true);
    final page = await _repo.fetch(after: null);
    // one write: the list never passes through empty
    value = PagedState(items: page.items, nextCursor: page.nextCursor);
  }
}

