// one owner, everyone watches it
class ProfileRepository {
  ProfileRepository(this._api);
  final ProfileApi _api;
  final _changes = StreamController<Profile>.broadcast();
  Profile? _cached;

  Stream<Profile> watch() async* {
    yield _cached ??= await _api.fetch();
    yield* _changes.stream;
  }

  Future<void> rename(String name) async {
    _cached = await _api.rename(name);
    _changes.add(_cached!);        // one write; every listener sees it
  }

  // an external event invalidates the OWNER, not each screen
  Future<void> invalidate() async {
    _cached = null;
    _changes.add(await _api.fetch());
  }

  void dispose() => _changes.close();
}

