sealed class CheckoutState {}

final class Idle extends CheckoutState {}
final class Submitting extends CheckoutState {}
final class AwaitingConfirmation extends CheckoutState {
  AwaitingConfirmation(this.paymentId);
  final String paymentId;
}
final class Paid extends CheckoutState {
  Paid(this.receipt);
  final Receipt receipt;   // a receipt screen is unreachable without one
}
final class Failed extends CheckoutState {
  Failed(this.reason);
  final String reason;
}

sealed class CheckoutEvent {}
final class Submitted extends CheckoutEvent {}
final class Accepted extends CheckoutEvent {
  Accepted(this.paymentId);
  final String paymentId;
}
final class Confirmed extends CheckoutEvent {
  Confirmed(this.receipt);
  final Receipt receipt;
}
final class Rejected extends CheckoutEvent {
  Rejected(this.reason);
  final String reason;
}
final class Retried extends CheckoutEvent {}

// pure and total: every pair has an answer, unlisted pairs stay put
CheckoutState next(CheckoutState s, CheckoutEvent e) => switch ((s, e)) {
      (Idle(), Submitted()) => Submitting(),
      (Submitting(), Accepted(:final paymentId)) => AwaitingConfirmation(paymentId),
      (AwaitingConfirmation(), Confirmed(:final receipt)) => Paid(receipt),
      (Submitting(), Rejected(:final reason)) ||
      (AwaitingConfirmation(), Rejected(:final reason)) => Failed(reason),
      (Failed(), Retried()) => Submitting(),
      _ => s,   // a duplicate Confirmed, or a late reply after a cancel
    };

// the table is the specification, so make it the test
void main() {
  final table = <(CheckoutState, CheckoutEvent, Type)>[
    (Idle(), Submitted(), Submitting),
    (Submitting(), Rejected('declined'), Failed),
    (Idle(), Confirmed(Receipt('r1')), Idle),          // ignored, not a crash
    (Paid(Receipt('r1')), Confirmed(Receipt('r1')), Paid),  // idempotent
  ];

  test('transition table', () {
    for (final (state, event, expected) in table) {
      expect(next(state, event).runtimeType, expected, reason: '$state + $event');
    }
  });
}

