const _currentVersion = 3;

typedef Migration = Map<String, dynamic> Function(Map<String, dynamic>);

// keyed by the version each one migrates FROM
final _migrations = <int, Migration>{
  1: (json) => {...json, 'plan': 'free'},              // added a field
  2: (json) => {                                       // split one field into two
        ...json,
        'firstName': (json['name'] as String).split(' ').first,
        'lastName': (json['name'] as String).split(' ').skip(1).join(' '),
      }..remove('name'),
};

Future<Settings> loadSettings(SharedPreferences prefs) async {
  final raw = prefs.getString('settings');
  if (raw == null) return Settings.initial();          // first launch, not an error

  try {
    final envelope = jsonDecode(raw) as Map<String, dynamic>;
    var version = envelope['v'] as int? ?? 1;
    if (version > _currentVersion) {
      throw StateError('written by a newer build (v$version)');
    }

    var data = envelope['data'] as Map<String, dynamic>;
    while (version < _currentVersion) {
      data = _migrations[version]!(data);               // chain, never one hop
      version++;
    }
    return Settings.fromJson(data);
  } catch (error, stack) {
    log('settings unreadable, dropping', error: error, stackTrace: stack);
    await prefs.remove('settings');   // drop it, or the next launch repeats this
    return Settings.initial();
  }
}

Future<void> saveSettings(SharedPreferences prefs, Settings s) => prefs.setString(
      'settings',
      jsonEncode({'v': _currentVersion, 'data': s.toJson()}),
    );

