// the performance: effects wrapped around the pure core
class SearchStore {
  SearchStore(this._repo, {DateTime Function()? now}) : _now = now ?? DateTime.now;

  final SearchRepository _repo;
  final DateTime Function() _now;          // injected, never called statically
  final _states = StreamController<SearchState>.broadcast();

  Stream<SearchState> get stream => _states.stream;
  SearchState state = Idle();

  void _apply(SearchEvent e) {
    final updated = next(state, e);
    if (updated == state) return;
    state = updated;
    _states.add(updated);
  }

  Future<void> search(String query) async {
    _apply(QuerySubmitted(query));
    try {
      _apply(ResultsArrived(await _repo.search(query), _now()));
    } catch (error) {
      _apply(SearchFailed(error));
    }
  }
}

